const datesBefore = [...inbox.messages].map(m => m.date);

// Hate this, but current time is recorded when the messages are written
// into the msgStore.
// The timestamp will likely be truncated to seconds, so wait until we can
// be sure it's changed.
await PromiseTestUtils.promiseDelay(2000);

// Without the delay, the saving attempt that follows sometimes
// fails. The code to save the encrypted draft fails, because
// it finds no recipients. Maybe after opening the window,
// some time is needed to correctly populate the compose window.
// eslint-disable-next-line mozilla/no-arbitrary-setTimeout
await new Promise(resolve => setTimeout(resolve, 100));
